function iso(now?: (() => number) | number): string { return new Date(typeof now === 'function' ? now() : now ?? Date.now()).toISOString(); }
function isLocalNetworkHost(hostname: string): boolean { const host = hostname.toLowerCase().replace(/\.$/, ''); return host === 'localhost' || host === '::1' || host.endsWith('.localhost') || host.endsWith('.local') || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host) || /^fc|^fd/i.test(host); }
